//
//  SwiftForgeTheme+Midnight.swift
//  SwiftForgeUI
//
//  Colors are generated by scripts/theme-design (see docs/design/themes/midnight.md)
//  and verified by SwiftForgeContrastAudit in every test run.
//

import SwiftUI

extension SwiftForgeTheme {

    /// Dark-first and high-contrast: an ink-navy canvas, neon accents, and
    /// medium-sharp corners (8-pt controls, 10-pt cards).
    ///
    /// In dark mode, raised surfaces glow faintly in the accent color and are
    /// outlined by luminous hairlines. Light mode inverts the identity:
    /// filled controls turn ink navy with neon-cyan labels, links and
    /// outlines deepen to a cyan that meets AA contrast on white, and shadows
    /// take on a navy tint. Titles are set heavier than in ``forge``, and
    /// motion is snappier.
    public static let midnight: SwiftForgeTheme = {
        typealias P = Palette.Midnight
        let accent = SwiftForgeToneColors(
            solid: SwiftForgeColor(
                light: P.Night.s900, dark: P.neonCyan, lightHighContrast: P.Night.s950, darkHighContrast: P.Cyan.s200),
            onSolid: SwiftForgeColor(
                light: P.neonCyan, dark: P.void, lightHighContrast: Palette.white, darkHighContrast: Palette.black),
            text: SwiftForgeColor(
                light: P.Cyan.s700, dark: P.neonCyan, lightHighContrast: P.Cyan.s800, darkHighContrast: P.Cyan.s200),
            subtle: SwiftForgeColor(
                light: P.Cyan.s50, dark: P.Cyan.s950, lightHighContrast: P.Cyan.s100, darkHighContrast: P.Cyan.s900)
        )
        let colors = SwiftForgeColors(
            canvas: SwiftForgeColor(light: P.Night.s50, dark: P.void),
            surface: SwiftForgeColor(light: Palette.white, dark: P.deep),
            surfaceRaised: SwiftForgeColor(light: Palette.white, dark: P.panel),
            fillMuted: SwiftForgeColor(light: P.Night.s100, dark: P.lift),
            textPrimary: SwiftForgeColor(
                light: P.Night.s950, dark: P.frost, lightHighContrast: Palette.black, darkHighContrast: Palette.white),
            textSecondary: SwiftForgeColor(
                light: P.Night.s700, dark: P.Night.s300, lightHighContrast: P.Night.s800, darkHighContrast: P.Night.s200),
            borderSubtle: SwiftForgeColor(
                light: P.Night.s200, dark: P.Night.s800, lightHighContrast: P.Night.s400, darkHighContrast: P.Night.s600),
            borderStrong: SwiftForgeColor(
                light: P.Night.s500, dark: P.Night.s500, lightHighContrast: P.Night.s700, darkHighContrast: P.Night.s300),
            focusRing: accent.text,
            pressedOverlay: SharedTokens.pressedOverlay,
            accent: accent,
            neutral: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Night.s800, dark: P.Night.s300, lightHighContrast: P.Night.s900, darkHighContrast: P.Night.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.void, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Night.s700, dark: P.Night.s300, lightHighContrast: P.Night.s800, darkHighContrast: P.Night.s200),
                subtle: SwiftForgeColor(
                    light: P.Night.s100, dark: P.lift, lightHighContrast: P.Night.s200, darkHighContrast: P.Night.s900)
            ),
            info: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Azure.s700, dark: P.neonAzure, lightHighContrast: P.Azure.s800, darkHighContrast: P.Azure.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.void, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Azure.s700, dark: P.neonAzure, lightHighContrast: P.Azure.s800, darkHighContrast: P.Azure.s200),
                subtle: SwiftForgeColor(
                    light: P.Azure.s50, dark: P.Azure.s950, lightHighContrast: P.Azure.s100, darkHighContrast: P.Azure.s900)
            ),
            success: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Jade.s700, dark: P.neonJade, lightHighContrast: P.Jade.s800, darkHighContrast: P.Jade.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.void, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Jade.s700, dark: P.neonJade, lightHighContrast: P.Jade.s800, darkHighContrast: P.Jade.s200),
                subtle: SwiftForgeColor(
                    light: P.Jade.s50, dark: P.Jade.s950, lightHighContrast: P.Jade.s100, darkHighContrast: P.Jade.s900)
            ),
            warning: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.neonAmber, dark: P.neonAmber, lightHighContrast: P.Amber.s300, darkHighContrast: P.Amber.s200),
                onSolid: SwiftForgeColor(light: Palette.black, dark: P.void, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Amber.s700, dark: P.neonAmber, lightHighContrast: P.Amber.s800, darkHighContrast: P.Amber.s200),
                subtle: SwiftForgeColor(
                    light: P.Amber.s50, dark: P.Amber.s950, lightHighContrast: P.Amber.s100, darkHighContrast: P.Amber.s900)
            ),
            danger: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Rose.s700, dark: P.neonRose, lightHighContrast: P.Rose.s800, darkHighContrast: P.Rose.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.void, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Rose.s700, dark: P.neonRose, lightHighContrast: P.Rose.s800, darkHighContrast: P.Rose.s200),
                subtle: SwiftForgeColor(
                    light: P.Rose.s50, dark: P.Rose.s950, lightHighContrast: P.Rose.s100, darkHighContrast: P.Rose.s900)
            )
        )
        return SwiftForgeTheme(
            id: "midnight",
            displayName: "Midnight",
            colors: colors,
            typography: SwiftForgeTypography.standard
                .updating([\.largeTitle, \.title1]) { $0.weight = .heavy }
                .updating([\.title2]) { $0.weight = .heavy }
                .updating([\.title3, \.headline, \.controlLabel, \.controlLabelSmall]) { $0.weight = .bold },
            radius: SwiftForgeRadius(
                xs: 2, sm: 4, md: 6, lg: 8, xl: 12, xxl: 16,
                control: 8, controlSmall: 6, card: 10, sheet: 16
            ),
            elevation: SwiftForgeElevation(
                low: SwiftForgeShadow(
                    color: SharedTokens.shadowColor(light: P.Night.s950, 0.10, dark: P.neonCyan, 0.14), radius: 4, y: 1),
                medium: SwiftForgeShadow(
                    color: SharedTokens.shadowColor(light: P.Night.s950, 0.14, dark: P.neonCyan, 0.20), radius: 16, y: 4),
                high: SwiftForgeShadow(
                    color: SharedTokens.shadowColor(light: P.Night.s950, 0.20, dark: P.neonCyan, 0.28), radius: 32, y: 10),
                raisedSurfacesHaveBorder: true
            ),
            motion: SwiftForgeMotion(
                fast: SwiftForgeMotionToken(duration: 0.16, bounce: 0.1),
                standard: SwiftForgeMotionToken(duration: 0.26),
                emphasized: SwiftForgeMotionToken(duration: 0.38, bounce: 0.1),
                shimmerDuration: 1.2,
                pressedScale: 0.96
            )
        )
    }()
}
